  "risk": {
    "level": "medium",
    "touches": ["wallet", "p2p"],
    "why": "Defaulting rebroadcast to false changes node behavior so stuck or evicted unconfirmed transactions will not automatically be rebroadcast, potentially leaving user transactions unconfirmed if network peers drop them."
  }
}
